package core.game.interaction;import core.game.component.Component;import core.game.node.entity.player.Player;public class InterfaceListeners{public static boolean runOpen(Player p,Component c){oracle.Support.emit("listenerOpen",oracle.Support.index(p),c.getId());return false;}public static boolean runClose(Player p,Component c){oracle.Support.emit("listenerClose",oracle.Support.index(p),c.getId());return true;}}